import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { createBrowserRouter } from "react-router";
import { RouterProvider } from "react-router/dom";
import "./index.css";
import Home from "./routes/Home";
import GuestView from "./routes/GuestView";
import NotFound from "./routes/NotFound";

const router = createBrowserRouter([
  { path: "/", element: <Home /> },
  { path: "/s/:shareId", element: <GuestView /> },
  { path: "*", element: <NotFound /> },
]);

const root = document.getElementById("root");
if (!root) throw new Error("Missing #root element");

createRoot(root).render(
  <StrictMode>
    <RouterProvider router={router} />
  </StrictMode>,
);

/**
 * Client for the share endpoints in services/api/README.md.
 *
 *   GET /api/shares/<shareId>        -> { shareId, format, assetPath }
 *   GET /api/shares/<shareId>/asset  -> the uploaded file (same access check)
 *
 * The API answers 404 both for an unknown share and for a private share the
 * viewer may not open, so the UI treats those as one "not found or no access" state.
 */

export type ScanFormat = "ply" | "glb";

export interface ShareMetadata {
  shareId: string;
  format: ScanFormat;
  assetPath: string;
}

export type ShareErrorKind = "not-found" | "network" | "server" | "bad-response";

export class ShareError extends Error {
  readonly kind: ShareErrorKind;
  readonly status?: number;

  constructor(kind: ShareErrorKind, message: string, status?: number) {
    super(message);
    this.name = "ShareError";
    this.kind = kind;
    this.status = status;
  }
}

async function request(url: string, signal: AbortSignal): Promise<Response> {
  let response: Response;
  try {
    response = await fetch(url, { signal, credentials: "same-origin" });
  } catch (error) {
    if (signal.aborted) throw error;
    throw new ShareError("network", "Could not reach the Path server.");
  }
  if (response.status === 404) {
    throw new ShareError("not-found", "This scan link doesn't exist or isn't shared with you.", 404);
  }
  if (!response.ok) {
    throw new ShareError("server", `The server answered ${response.status}.`, response.status);
  }
  return response;
}

function isShareMetadata(value: unknown): value is ShareMetadata {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.shareId === "string" &&
    (v.format === "ply" || v.format === "glb") &&
    typeof v.assetPath === "string" &&
    v.assetPath.length > 0
  );
}

export async function fetchShare(shareId: string, signal: AbortSignal): Promise<ShareMetadata> {
  const response = await request(`/api/shares/${encodeURIComponent(shareId)}`, signal);
  let body: unknown;
  try {
    body = await response.json();
  } catch {
    throw new ShareError("bad-response", "The share details weren't valid JSON.");
  }
  if (!isShareMetadata(body)) {
    throw new ShareError("bad-response", "The share details were missing a format or asset path.");
  }
  return body;
}

/** Fetches the scan bytes. `assetPath` may be relative to this site or an absolute URL. */
export async function fetchAsset(assetPath: string, signal: AbortSignal): Promise<ArrayBuffer> {
  const url = new URL(assetPath, window.location.origin).toString();
  const response = await request(url, signal);
  try {
    return await response.arrayBuffer();
  } catch (error) {
    if (signal.aborted) throw error;
    throw new ShareError("network", "The scan download was interrupted.");
  }
}

import { BufferAttribute, BufferGeometry, Sphere, Vector3 } from "three";
import { PLYLoader } from "three/examples/jsm/loaders/PLYLoader.js";

/** Above this many points, keep an evenly spaced subset so phones stay interactive. */
export const MAX_POINTS = 600_000;

export class ScanParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ScanParseError";
  }
}

export interface PointScan {
  geometry: BufferGeometry;
  /** Points in the file before any downsampling. */
  sourceCount: number;
  /** Points actually rendered. */
  count: number;
  hasColor: boolean;
  bounds: Sphere;
}

function downsample(geometry: BufferGeometry, keep: number): BufferGeometry {
  const total = geometry.getAttribute("position").count;
  const stride = total / keep;
  const out = new BufferGeometry();
  for (const name of ["position", "color"] as const) {
    const source = geometry.getAttribute(name);
    if (!source) continue;
    const size = source.itemSize;
    const data = new Float32Array(keep * size);
    for (let i = 0; i < keep; i++) {
      const from = Math.floor(i * stride);
      for (let c = 0; c < size; c++) data[i * size + c] = source.array[from * size + c] ?? 0;
    }
    out.setAttribute(name, new BufferAttribute(data, size));
  }
  geometry.dispose();
  return out;
}

/**
 * Parses an ASCII or binary PLY with XYZ positions and optional uchar RGB colors.
 * PLYLoader converts the sRGB vertex colors to linear, which is what three expects.
 */
export function parsePointCloud(buffer: ArrayBuffer): PointScan {
  const header = new TextDecoder().decode(buffer.slice(0, Math.min(buffer.byteLength, 3)));
  if (header !== "ply") throw new ScanParseError("The file isn't a PLY scan (missing the “ply” header).");

  let geometry: BufferGeometry;
  try {
    geometry = new PLYLoader().parse(buffer);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new ScanParseError(`The PLY couldn't be read: ${detail}`);
  }

  const position = geometry.getAttribute("position");
  if (!position || position.count === 0) {
    throw new ScanParseError("The PLY has no points.");
  }
  for (let i = 0; i < position.array.length; i++) {
    if (!Number.isFinite(position.array[i])) {
      throw new ScanParseError("The PLY has coordinates that aren't finite numbers.");
    }
  }

  const sourceCount = position.count;
  if (sourceCount > MAX_POINTS) geometry = downsample(geometry, MAX_POINTS);

  geometry.computeBoundingSphere();
  const bounds = geometry.boundingSphere?.clone() ?? new Sphere(new Vector3(), 1);
  if (bounds.radius <= 0) bounds.radius = 1;

  return {
    geometry,
    sourceCount,
    count: geometry.getAttribute("position").count,
    hasColor: Boolean(geometry.getAttribute("color")),
    bounds,
  };
}

import { OrbitControls } from "@react-three/drei";
import { Canvas, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import { CanvasTexture, MathUtils, MOUSE, TOUCH, type Texture } from "three";
import type { OrbitControls as OrbitControlsImpl } from "three-stdlib";
import type { PointScan } from "../lib/ply";

const NIGHT = "#121C16";

/** A soft round sprite so points read as dots rather than squares. */
function useDotTexture(): Texture {
  return useMemo(() => {
    const size = 64;
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.beginPath();
      ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
    }
    return new CanvasTexture(canvas);
  }, []);
}

/**
 * World-space point size from scan density: sparse scans (like the 93-point fixture)
 * get large dots so shapes stay readable, dense phone scans get fine ones.
 */
function pointSizeFor(scan: PointScan): number {
  const spacing = scan.bounds.radius / Math.sqrt(scan.count);
  return MathUtils.clamp(spacing * 0.7, 0.008, 0.3);
}

function Points({ scan }: { scan: PointScan }) {
  const dot = useDotTexture();
  const size = pointSizeFor(scan);
  useEffect(() => () => dot.dispose(), [dot]);
  return (
    <points geometry={scan.geometry} frustumCulled={false}>
      <pointsMaterial
        size={size}
        sizeAttenuation
        vertexColors={scan.hasColor}
        color={scan.hasColor ? "#ffffff" : "#A9C4AE"}
        map={dot}
        alphaTest={0.5}
        transparent={false}
      />
    </points>
  );
}

/**
 * Frames the scan from behind and above the entrance. The event frame puts the
 * entrance at the origin with −Z forward, so a camera on +Z looks down the corridor
 * the way a guest walking in would.
 */
function Framing({ scan, resetToken }: { scan: PointScan; resetToken: number }) {
  const camera = useThree((s) => s.camera);
  const controls = useThree((s) => s.controls) as OrbitControlsImpl | null;

  useEffect(() => {
    const { center, radius } = scan.bounds;
    camera.position.set(center.x, center.y + radius * 1.1, center.z + radius * 1.5);
    camera.near = Math.max(radius / 1000, 0.001);
    camera.far = radius * 50;
    camera.updateProjectionMatrix();
    if (controls) {
      controls.target.copy(center);
      controls.minDistance = radius * 0.05;
      controls.maxDistance = radius * 6;
      controls.update();
    } else {
      camera.lookAt(center);
    }
  }, [scan, camera, controls, resetToken]);

  return null;
}

export interface ScanViewerProps {
  scan: PointScan;
  /** Change this number to put the camera back to the starting view. */
  resetToken: number;
  onReady?: () => void;
}

export default function ScanViewer({ scan, resetToken, onReady }: ScanViewerProps) {
  const readyRef = useRef(false);

  return (
    <Canvas
      dpr={[1, 2]}
      camera={{ fov: 55 }}
      gl={{ antialias: true, powerPreference: "high-performance" }}
      onCreated={() => {
        if (!readyRef.current) {
          readyRef.current = true;
          onReady?.();
        }
      }}
      aria-hidden="true"
    >
      <color attach="background" args={[NIGHT]} />
      <Points scan={scan} />
      <OrbitControls
        makeDefault
        enableDamping
        dampingFactor={0.08}
        rotateSpeed={0.7}
        zoomSpeed={0.9}
        maxPolarAngle={Math.PI * 0.92}
        touches={{ ONE: TOUCH.ROTATE, TWO: TOUCH.DOLLY_PAN }}
        mouseButtons={{ LEFT: MOUSE.ROTATE, MIDDLE: MOUSE.DOLLY, RIGHT: MOUSE.PAN }}
      />
      <Framing scan={scan} resetToken=REDACTED />
    </Canvas>
  );
}

